import { useState, useMemo } from "react";
import { Input, Select, Button, Modal, Form, InputNumber, App, Dropdown, Typography } from "antd";
import { SearchOutlined, MoreOutlined, ShoppingOutlined, CarOutlined, CreditCardOutlined, BankOutlined } from "@ant-design/icons";
import { useTranslation } from "react-i18next";
import type { ColumnsType } from "antd/es/table";
import type { MenuProps } from "antd";
import type { Transaction } from "@kawkaw/shared";
import dayjs from "dayjs";
import { useNavigate } from "react-router-dom";
import { DataTable } from "../components/DataTable";
import { AdminShell } from "../layouts/AdminShell";
import { useAdminTransactions, useInitiateRefund, useAdminTransaction } from "../api/hooks";
import { tokens } from "../styles/tokens";
const { color: T } = tokens;
import { ReceiptModal, type ReceiptTxn } from "./ReceiptModal";

const { Text } = Typography;

// Backend transaction includes order join: { id, order_code, type, total }
type TxnWithOrder = Transaction & {
  reference: string | null;
  method: string;
  order?: { id: string; order_code: string; type: string; total: string };
};

function TxnStatusPill({ status }: { status: string }) {
  const { t } = useTranslation();
  const styleMap: Record<string, { bg: string; color: string }> = {
    success:        { bg: T.successDeep, color: T.surface },
    partial_refund: { bg: T.brand, color: T.surface },
    refunded:       { bg: T.dangerBg, color: T.dangerText },
    pending:        { bg: "#FEF9C3", color: T.warningDeep },
    failed:         { bg: T.surfaceSection, color: T.textSecondary },
  };
  const labelKey: Record<string, string> = {
    success: "transactions.statusSuccess",
    partial_refund: "transactions.statusPartialRefund",
    refunded: "transactions.statusRefunded",
    pending: "transactions.statusPending",
    failed: "transactions.statusFailed",
  };
  const s = styleMap[status] ?? { bg: T.surfaceSection, color: T.textSecondary };
  const label = labelKey[status] ? t(labelKey[status]) : status.replace(/_/g, " ");
  return (
    <span style={{
      background: s.bg, color: s.color, borderRadius: 20,
      padding: "4px 12px", fontSize: 11, fontWeight: 700,
      textTransform: "uppercase", letterSpacing: 0.5, whiteSpace: "nowrap",
    }}>
      {label}
    </span>
  );
}

export function TransactionsScreen() {
  const { t } = useTranslation();
  const { message } = App.useApp();
  const navigate = useNavigate();
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState("");
  const [status, setStatus] = useState<string | undefined>();
  const [method, setMethod] = useState<string | undefined>();
  const [datePreset, setDatePreset] = useState("7d");
  const [refundTarget, setRefundTarget] = useState<TxnWithOrder | null>(null);
  const [refundForm] = Form.useForm();
  const initiateRefund = useInitiateRefund();
  const [receiptTxnId, setReceiptTxnId] = useState<string | undefined>();
  const { data: receiptTxnData } = useAdminTransaction(receiptTxnId);

  const dateRange = useMemo(() => {
    const days = datePreset === "7d" ? 7 : datePreset === "30d" ? 30 : datePreset === "90d" ? 90 : null;
    if (!days) return {};
    return {
      from: dayjs().subtract(days, "day").startOf("day").toISOString(),
      to: dayjs().endOf("day").toISOString(),
    };
  }, [datePreset]);

  const datePresetOptions = useMemo(
    () => [
      { value: "7d", label: t("transactions.datePreset7d") },
      { value: "30d", label: t("transactions.datePreset30d") },
      { value: "90d", label: t("transactions.datePreset90d") },
      { value: "all", label: t("transactions.datePresetAll") },
    ],
    [t],
  );

  const refundMethodOptions = useMemo(
    () => [
      { value: "cash", label: t("refunds.payCash") },
      { value: "fpx", label: t("refunds.payFpx") },
      { value: "visa", label: t("refunds.payVisa") },
      { value: "grabpay", label: t("refunds.payGrab") },
      { value: "tng", label: t("refunds.payTng") },
      { value: "boost", label: t("refunds.payBoost") },
      { value: "ewallet", label: t("refunds.payEwallet") },
    ],
    [t],
  );

  const paymentFilterOptions = useMemo(
    () => [
      { value: "cash", label: t("refunds.payCash") },
      { value: "fpx", label: t("refunds.payFpx") },
      { value: "visa", label: t("refunds.payVisa") },
      { value: "grabpay", label: t("refunds.payGrab") },
      { value: "tng", label: t("refunds.payTng") },
      { value: "ewallet", label: t("refunds.payEwallet") },
    ],
    [t],
  );

  const statusFilterOptions = useMemo(
    () => [
      { value: "success", label: t("transactions.statusSuccess") },
      { value: "pending", label: t("transactions.statusPending") },
      { value: "partial_refund", label: t("transactions.statusPartialRefund") },
      { value: "refunded", label: t("transactions.statusRefunded") },
      { value: "failed", label: t("transactions.statusFailed") },
    ],
    [t],
  );

  const orderTypeFilterOptions = useMemo(
    () => [
      { value: "pickup", label: t("orders.type.pickup") },
      { value: "delivery", label: t("orders.type.delivery") },
    ],
    [t],
  );

  const paymentMethodLabel = useMemo(() => {
    const map: Record<string, string> = {
      cash: t("refunds.payCash"),
      fpx: t("refunds.payFpx"),
      visa: t("refunds.payVisa"),
      grabpay: t("refunds.payGrab"),
      tng: t("refunds.payTng"),
      boost: t("refunds.payBoost"),
      ewallet: t("refunds.payEwallet"),
    };
    return (m: string) => map[m] ?? m.toUpperCase();
  }, [t]);

  const { data, isLoading } = useAdminTransactions({
    page, limit: 20,
    q: search || undefined,
    status,
    method,
    ...dateRange,
  });

  const txns = (data?.data ?? []) as TxnWithOrder[];
  const totalCount = data?.meta.total ?? 0;

  const onRefundSubmit = async (values: { amount: number; reason: string; type: "full" | "partial"; method: string }) => {
    if (!refundTarget?.order?.id) return;
    try {
      await initiateRefund.mutateAsync({
        orderId: refundTarget.order.id,
        amount: values.amount.toFixed(2),
        type: values.type,
        reason: values.reason,
        method: values.method,
      });
      void message.success(t("transactions.refundInitiated"));
      setRefundTarget(null);
      refundForm.resetFields();
    } catch {
      void message.error(t("transactions.refundFailed"));
    }
  };

  const TH = (label: string) => (
    <span style={{ fontSize: 11, fontWeight: 700, letterSpacing: 0.5, color: T.textMuted, textTransform: "uppercase" }}>{label}</span>
  );

  const columns: ColumnsType<TxnWithOrder> = useMemo(() => [
    {
      title: TH(t("transactions.colTxnId")),
      dataIndex: "reference", key: "ref", width: 160,
      render: (v) => <Text style={{ fontSize: 12, color: T.textBody, fontFamily: "monospace" }}>{(v as string) ?? "—"}</Text>,
    },
    {
      title: TH(t("transactions.colCustomerOrder")),
      key: "customer_order", width: 180,
      render: (_, row) => (
        <div>
          <div style={{ fontSize: 14, fontWeight: 600, color: T.textDark }}>{t("transactions.customerLabel")}</div>
          <div style={{ fontSize: 12, color: T.textMuted }}>#{row.order?.order_code ?? "—"}</div>
        </div>
      ),
    },
    {
      title: TH(t("transactions.colOrderType")),
      key: "order_type", width: 120,
      render: (_, row) => (
        <div style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 13, color: T.textBody }}>
          {row.order?.type === "delivery" ? <CarOutlined /> : <ShoppingOutlined />}
          {row.order?.type === "delivery" ? t("orders.type.delivery") : t("orders.type.pickup")}
        </div>
      ),
    },
    {
      title: TH(t("transactions.colAmount")),
      dataIndex: "amount", key: "amount", width: 120,
      render: (v, row) => (
        <div>
          <div style={{ fontSize: 15, fontWeight: 700, color: T.textDark }}>RM {Number(v as string).toFixed(2)}</div>
          {row.status === "partial_refund" && (
            <div style={{ fontSize: 12, color: T.brand, marginTop: 2 }}>{t("transactions.partialRefNote")}</div>
          )}
        </div>
      ),
    },
    {
      title: TH(t("transactions.colPayment")),
      dataIndex: "method", key: "method", width: 160,
      render: (v) => (
        <div style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 13, color: T.textBody }}>
          {(v as string) === "fpx" ? <BankOutlined /> : <CreditCardOutlined />}
          {paymentMethodLabel(v as string)}
        </div>
      ),
    },
    {
      title: TH(t("transactions.colStatus")),
      dataIndex: "status", key: "status", width: 160,
      render: (v) => <TxnStatusPill status={v as string} />,
    },
    {
      title: TH(t("transactions.colDateTime")),
      dataIndex: "paid_at", key: "date", width: 140,
      render: (v) => v ? (
        <div style={{ fontSize: 12, color: T.textBody, lineHeight: 1.6 }}>
          <div>{dayjs(v as string).format("MMM DD, YYYY")}</div>
          <div>{dayjs(v as string).format("h:mm A")}</div>
        </div>
      ) : "—",
    },
    {
      title: "", key: "actions", width: 50, fixed: "right",
      render: (_, row) => {
        const items: MenuProps["items"] = [
          {
            key: "view",
            label: <span style={{ fontSize: 12, fontWeight: 700, letterSpacing: 0.5 }}>{t("transactions.actionViewDetails")}</span>,
            onClick: () => { navigate(`/transactions/${row.id}`); },
          },
          {
            key: "refund",
            label: <span style={{ fontSize: 12, fontWeight: 700, letterSpacing: 0.5 }}>{t("transactions.actionRefunds")}</span>,
            disabled: row.status !== "success",
            onClick: () => { navigate(`/transactions/${row.id}/refund`); },
          },
          {
            key: "receipt",
            label: <span style={{ fontSize: 12, fontWeight: 700, letterSpacing: 0.5 }}>{t("transactions.actionReceipt")}</span>,
            onClick: () => { setReceiptTxnId(row.id); },
          },
        ];
        return (
          <Dropdown menu={{ items }} trigger={["click"]}>
            <Button type="text" icon={<MoreOutlined />} style={{ padding: "0 8px" }} />
          </Dropdown>
        );
      },
    },
  ], [t, navigate, paymentMethodLabel]);

  return (
    <>
    <AdminShell>
      <div style={{ padding: "28px 32px", background: T.bg, minHeight: "100vh" }}>
        {/* Page title */}
        <div style={{ fontSize: 26, fontWeight: 800, color: T.textDark, marginBottom: 24 }}>{t("transactions.pageTitle")}</div>

        {/* Stat cards */}
        <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 16, marginBottom: 24 }}>
          {([
            { label: t("transactions.statTotalTxns"), value: totalCount.toLocaleString(), valueColor: T.textDark },
            { label: t("transactions.statTotalRevenue"),  value: "—",                           valueColor: T.textDark },
            { label: t("transactions.statTotalRefunded"), value: "—",                           valueColor: T.dangerText },
            { label: t("transactions.statNetRevenue"),    value: "—",                           valueColor: T.textDark },
          ] as { label: string; value: string; valueColor: string }[]).map(card => (
            <div key={card.label} style={{
              background: T.surface, borderRadius: 12,
              border: "1px solid #E5E7EB", padding: "20px 24px",
            }}>
              <div style={{ fontSize: 11, fontWeight: 700, color: T.textMuted, letterSpacing: 0.8, textTransform: "uppercase", marginBottom: 12 }}>
                {card.label}
              </div>
              <div style={{ fontSize: 28, fontWeight: 800, color: card.valueColor, lineHeight: 1.2 }}>
                {card.value}
              </div>
            </div>
          ))}
        </div>

        {/* Filter bar */}
        <div style={{ background: T.surface, borderRadius: 12, border: "1px solid #E5E7EB", padding: "16px 20px", marginBottom: 20 }}>
          <div style={{ display: "flex", gap: 10, flexWrap: "wrap", alignItems: "center" }}>
            <Input
              prefix={<SearchOutlined style={{ color: T.textMuted }} />}
              placeholder={t("transactions.searchPlaceholderWide")}
              value={search}
              onChange={(e) => { setSearch(e.target.value); setPage(1); }}
              style={{ flex: 1, minWidth: 240, borderRadius: 8, height: 40 }}
              allowClear
            />
            <Select
              value={datePreset}
              onChange={(v) => { setDatePreset(v as string); setPage(1); }}
              style={{ width: 150, height: 40 }}
              options={datePresetOptions}
            />
            <Select
              placeholder={t("transactions.filterAllPaymentMethods")}
              allowClear
              value={method}
              onChange={(v) => { setMethod(v as string | undefined); setPage(1); }}
              style={{ width: 190, height: 40 }}
              options={paymentFilterOptions}
            />
            <Select
              placeholder={t("transactions.filterAllStatus")}
              allowClear
              value={status}
              onChange={(v) => { setStatus(v as string | undefined); setPage(1); }}
              style={{ width: 160, height: 40 }}
              options={statusFilterOptions}
            />
            <Select
              placeholder={t("transactions.filterAllOrderTypes")}
              allowClear
              style={{ width: 160, height: 40 }}
              options={orderTypeFilterOptions}
            />
          </div>
        </div>

        {/* Table */}
        <div style={{ background: T.surface, borderRadius: 12, border: "1px solid #E5E7EB", overflow: "hidden" }}>
          <DataTable<TxnWithOrder>
            columns={columns}
            dataSource={txns}
            loading={isLoading}
            pagination={{ current: page, total: totalCount, pageSize: 20, onChange: (p) => setPage(p) }}
          />
        </div>
      </div>

      {/* Initiate Refund Modal */}
      <Modal
        open={!!refundTarget}
        title={`${t("transactions.refundModalTitle")} — ${refundTarget?.order?.order_code ?? t("orders.colOrderId")}`}
        onCancel={() => { setRefundTarget(null); refundForm.resetFields(); }}
        onOk={() => void refundForm.submit()}
        okText={t("transactions.submitRefund")}
        okButtonProps={{ danger: true, loading: initiateRefund.isPending }}
        destroyOnHidden
      >
        <p style={{ marginBottom: 16, color: T.textSecondary }}>
          {t("transactions.refundOriginal")} <b>RM {refundTarget?.amount}</b> · {t("transactions.refundPaidVia")} <b>{refundTarget?.method?.toUpperCase()}</b>
        </p>
        <Form form={refundForm} layout="vertical" onFinish={onRefundSubmit}>
          <Form.Item name="type" label={t("transactions.refundType")} rules={[{ required: true }]}>
            <Select options={[
              { value: "full", label: t("transactions.refundTypeFull") },
              { value: "partial", label: t("transactions.refundTypePartial") },
            ]} />
          </Form.Item>
          <Form.Item name="amount" label={t("transactions.refundAmount")}
            rules={[{ required: true }, { type: "number", min: 0.01, max: parseFloat(refundTarget?.amount ?? "0") }]}>
            <InputNumber prefix="RM" min={0.01} max={parseFloat(refundTarget?.amount ?? "0")} precision={2} style={{ width: "100%" }} />
          </Form.Item>
          <Form.Item name="method" label={t("transactions.refundMethod")} rules={[{ required: true }]}>
            <Select options={refundMethodOptions} />
          </Form.Item>
          <Form.Item name="reason" label={t("transactions.refundReason")} rules={[{ required: true, min: 3 }]}>
            <Input.TextArea rows={3} placeholder={t("transactions.refundReasonPlaceholder")} />
          </Form.Item>
        </Form>
      </Modal>
    </AdminShell>

    {receiptTxnData?.order?.kopitiam && receiptTxnData?.order?.items && (
      <ReceiptModal
        open={!!receiptTxnId}
        onClose={() => setReceiptTxnId(undefined)}
        txn={receiptTxnData as ReceiptTxn}
      />
    )}
  </>
  );
}
