import { useState, useMemo } from "react";
import {
  Input, Select, Button, Modal, Form, Dropdown, App, Typography, Divider, DatePicker,
} from "antd";
import type { MenuProps } from "antd";
import {
  SearchOutlined, MoreOutlined, DownloadOutlined,
  DollarOutlined, FileTextOutlined, PieChartOutlined, ClockCircleOutlined,
  RiseOutlined, WarningOutlined,
} from "@ant-design/icons";
import type { ColumnsType } from "antd/es/table";
import type { RangePickerProps } from "antd/es/date-picker";
import dayjs from "dayjs";
import { useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import { DataTable } from "../components/DataTable";
import { AdminShell } from "../layouts/AdminShell";
import {
  useAdminRefunds, useReviewRefund, useRefundStats,
  type AdminRefundItem,
} from "../api/hooks";
import { tokens } from "../styles/tokens";
const { color: T } = tokens;

const { Text } = Typography;
const { RangePicker } = DatePicker;

// ─── Constants ───────────────────────────────────────────────────────────────

const PAYMENT_I18N_KEYS: Record<string, string> = {
  visa: "refunds.payVisa", fpx: "refunds.payFpx", grabpay: "refunds.payGrab",
  cash: "refunds.payCash", ewallet: "refunds.payEwallet", tng: "refunds.payTng", boost: "refunds.payBoost",
};

const STATUS_STYLES: Record<string, { bg: string; color: string; labelKey: string }> = {
  success:  { bg: T.successBgAlt, color: "#065F46", labelKey: "refunds.pillSuccess" },
  pending:  { bg: T.warningBg, color: T.brandAmberText, labelKey: "refunds.pillPending" },
  rejected: { bg: T.dangerBg, color: T.dangerDeep, labelKey: "refunds.pillRejected" },
  failed:   { bg: T.surfaceSection, color: T.textSecondary, labelKey: "refunds.pillFailed" },
};

const TYPE_STYLES: Record<string, { bg: string; color: string; labelKey: string }> = {
  full:    { bg: T.brandLight, color: T.brandWarm, labelKey: "refunds.typeFullRef" },
  partial: { bg: "#FFFBEB", color: T.brandAmber, labelKey: "refunds.typePartialRef" },
};

// ─── Helpers ─────────────────────────────────────────────────────────────────

function refundDisplayId(id: string) {
  return `RFD-${id.slice(-3).toUpperCase().padStart(3, "0")}`;
}

function txnDisplayId(ref: string | null, id: string) {
  if (ref) return ref.toUpperCase();
  return `TXN-${id.slice(0, 12).toUpperCase()}`;
}

function StatusPill({ status }: { status: string }) {
  const { t } = useTranslation();
  const s = STATUS_STYLES[status] ?? { bg: T.surfaceSection, color: T.textSecondary, labelKey: "" };
  const label = s.labelKey ? t(s.labelKey) : status.toUpperCase();
  return (
    <span style={{
      display: "inline-flex", alignItems: "center", gap: 5,
      background: s.bg, color: s.color, borderRadius: 20,
      padding: "3px 10px", fontSize: 11, fontWeight: 700, letterSpacing: 0.3,
    }}>
      <span style={{ width: 6, height: 6, borderRadius: "50%", background: s.color, display: "inline-block" }} />
      {label}
    </span>
  );
}

function TypeBadge({ type }: { type: string }) {
  const { t } = useTranslation();
  const b = TYPE_STYLES[type] ?? { bg: T.surfaceSection, color: T.textSecondary, labelKey: "" };
  const label = b.labelKey ? t(b.labelKey) : type.toUpperCase();
  return (
    <span style={{
      background: b.bg, color: b.color, borderRadius: 4,
      padding: "2px 8px", fontSize: 10, fontWeight: 800, letterSpacing: 0.5,
    }}>
      {label}
    </span>
  );
}

// ─── Update Status Modal ─────────────────────────────────────────────────────

function UpdateStatusModal({
  refund,
  onClose,
}: {
  refund: AdminRefundItem;
  onClose: () => void;
}) {
  const { t } = useTranslation();
  const { message } = App.useApp();
  const [form] = Form.useForm();
  const reviewRefund = useReviewRefund();
  const [selectedStatus, setSelectedStatus] = useState<string>("completed");

  const onSubmit = async (vals: {
    status: string;
    transfer_method?: string;
    transfer_time?: string;
    reference_note?: string;
  }) => {
    const action = vals.status === "rejected" ? "reject" : "approve";
    try {
      await reviewRefund.mutateAsync({
        id: refund.id,
        action,
        note: vals.reference_note,
        transfer_method: vals.transfer_method,
        transfer_time: vals.transfer_time,
      });
      void message.success(t("refunds.statusUpdated"));
      onClose();
    } catch {
      void message.error(t("refunds.statusUpdateFailed"));
    }
  };

  const rfdId = refundDisplayId(refund.id);
  const txnRef = txnDisplayId(refund.transaction?.reference ?? null, refund.transaction_id);
  const orderCode = refund.order?.order_code ?? "—";
  const customerName = refund.order?.customer?.name ?? t("common.guest");
  const curSt = STATUS_STYLES[refund.status] ?? { bg: T.surfaceSection, color: T.textSecondary, labelKey: "" };
  const currentStatusLabel = curSt.labelKey ? t(curSt.labelKey) : refund.status.toUpperCase();
  const typeSt = TYPE_STYLES[refund.type] ?? { bg: T.surfaceSection, color: T.textSecondary, labelKey: "" };
  const typeLabel = typeSt.labelKey ? t(typeSt.labelKey) : refund.type.toUpperCase();

  return (
    <Modal
      open
      onCancel={onClose}
      footer={null}
      width={720}
      centered
      destroyOnHidden
      title={
        <div>
          <div style={{ fontSize: 18, fontWeight: 800, color: T.receiptBg }}>{t("refunds.modalTitle")}</div>
          <div style={{ fontSize: 13, color: T.brand, fontWeight: 600, marginTop: 2 }}>
            {t("refunds.modalRefundId")} {rfdId}
          </div>
        </div>
      }
      styles={{ body: { paddingTop: 20 } }}
    >
      {/* Summary row */}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16, marginBottom: 24 }}>
        {/* Refund summary */}
        <div style={{ background: T.bg, borderRadius: 12, padding: "16px 20px", border: "1px solid #E5E7EB" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 16 }}>
            <div style={{ background: T.brandLight, borderRadius: 8, padding: 6 }}>
              <WarningOutlined style={{ color: T.brand, fontSize: 14 }} />
            </div>
            <span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.8, color: T.textBody, textTransform: "uppercase" }}>
              {t("refunds.summaryTitle")}
            </span>
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            {[
              { label: t("refunds.customer"), value: customerName },
              { label: t("refunds.orderId"), value: `#${orderCode}` },
              { label: t("refunds.transactionId"), value: txnRef },
            ].map(({ label, value }) => (
              <div key={label} style={{ display: "flex", justifyContent: "space-between" }}>
                <span style={{ fontSize: 13, color: T.textBody }}>{label}</span>
                <span style={{ fontSize: 13, fontWeight: 700, color: T.textDark }}>{value}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Refund amount */}
        <div style={{ background: T.surface, borderRadius: 12, padding: "16px 20px", border: "1px solid #E5E7EB" }}>
          <div style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.8, color: T.textBody, textTransform: "uppercase", marginBottom: 12 }}>
            {t("refunds.refundAmount")}
          </div>
          <div style={{ fontSize: 32, fontWeight: 900, color: T.textDark, marginBottom: 10 }}>
            RM {Number(refund.amount).toFixed(2)}
          </div>
          <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
            <span style={{ background: typeSt.bg, color: typeSt.color, borderRadius: 4, padding: "2px 8px", fontSize: 10, fontWeight: 800 }}>
              {typeLabel}
            </span>
            <span style={{ fontSize: 12, color: T.textBody }}>{t("refunds.currentStatus")}</span>
            <span style={{ background: curSt.bg, color: curSt.color, borderRadius: 20, padding: "2px 8px", fontSize: 11, fontWeight: 700 }}>
              {currentStatusLabel}
            </span>
          </div>
        </div>
      </div>

      <Form form={form} layout="vertical" onFinish={vals => void onSubmit(vals as Parameters<typeof onSubmit>[0])}
        initialValues={{ status: "completed" }}>
        <Form.Item name="status" label={<span style={{ fontWeight: 700 }}>{t("refunds.updateStatus")}</span>}>
          <Select
            size="large"
            style={{ borderRadius: 8 }}
            onChange={(v) => setSelectedStatus(v as string)}
            options={[
              { value: "completed", label: t("refunds.optCompleted") },
              { value: "rejected",  label: t("refunds.optRejected") },
            ]}
          />
        </Form.Item>

        {selectedStatus === "completed" && (
          <div style={{ border: "1px solid #E5E7EB", borderRadius: 12, padding: "16px 20px", marginBottom: 16 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 16 }}>
              <div style={{ background: T.surfaceGreen, borderRadius: 8, padding: 6 }}>
                <DollarOutlined style={{ color: T.successBright, fontSize: 14 }} />
              </div>
              <span style={{ fontSize: 12, fontWeight: 800, letterSpacing: 0.6, color: T.successBright, textTransform: "uppercase" }}>
                {t("refunds.transferDetails")}
              </span>
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, marginBottom: 12 }}>
              <Form.Item name="transfer_method" label={t("refunds.transferMethod")} style={{ marginBottom: 0 }}>
                <Select
                  options={[
                    { value: "E-wallet", label: t("refunds.transferEwallet") },
                    { value: "Bank Transfer", label: t("refunds.transferBank") },
                    { value: "Cash", label: t("refunds.transferCash") },
                    { value: "FPX", label: t("refunds.transferFpx") },
                    { value: "Card", label: t("refunds.transferCard") },
                  ]}
                  placeholder={t("refunds.placeholderTransferMethod")}
                />
              </Form.Item>
              <Form.Item name="transfer_time" label={t("refunds.transferTime")} style={{ marginBottom: 0 }}>
                <Input placeholder={t("refunds.placeholderTransferTime")} />
              </Form.Item>
            </div>
            <Form.Item name="reference_note" label={t("refunds.referenceNote")} style={{ marginBottom: 0 }}>
              <Input.TextArea rows={2} placeholder={t("refunds.placeholderReference")} />
            </Form.Item>
          </div>
        )}

        {selectedStatus === "rejected" && (
          <Form.Item name="reference_note" label={t("refunds.rejectionReason")}>
            <Input.TextArea rows={3} placeholder={t("refunds.placeholderRejection")} />
          </Form.Item>
        )}

        {/* Warning */}
        <div style={{
          background: "#FEF2F2", border: "1px solid #FECACA", borderRadius: 8,
          padding: "12px 16px", display: "flex", gap: 10, alignItems: "flex-start", marginBottom: 20,
        }}>
          <WarningOutlined style={{ color: T.dangerText, marginTop: 1 }} />
          <span style={{ fontSize: 13, color: T.dangerText }}>
            {t("refunds.warnConfirmTransfer")}
          </span>
        </div>

        <div style={{ display: "flex", justifyContent: "flex-end", gap: 12 }}>
          <Button size="large" onClick={onClose} style={{ borderRadius: 8, minWidth: 100, fontWeight: 700 }}>
            {t("refunds.cancel").toUpperCase()}
          </Button>
          <Button
            size="large"
            type="primary"
            htmlType="submit"
            loading={reviewRefund.isPending}
            style={{ borderRadius: 8, minWidth: 160, background: T.brand, borderColor: T.brand, fontWeight: 800 }}
          >
            {t("refunds.confirmUpdate").toUpperCase()}
          </Button>
        </div>
      </Form>
    </Modal>
  );
}

// ─── Main screen ─────────────────────────────────────────────────────────────

export function RefundsScreen() {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const [page, setPage] = useState(1);
  const [status, setStatus] = useState<string | undefined>();
  const [type, setType] = useState<string | undefined>();
  const [method, setMethod] = useState<string | undefined>();
  const [search, setSearch] = useState("");
  const [dateRange, setDateRange] = useState<[string, string] | null>(null);
  const [updateTarget, setUpdateTarget] = useState<AdminRefundItem | null>(null);

  const filterParams = useMemo(() => ({
    page, limit: 20,
    status: status || undefined,
    type: type || undefined,
    method: method || undefined,
    q: search || undefined,
    from: dateRange?.[0] || undefined,
    to: dateRange?.[1] || undefined,
  }), [page, status, type, method, search, dateRange]);

  const { data, isLoading } = useAdminRefunds(filterParams);
  const { data: stats } = useRefundStats();

  const refunds = (data?.data ?? []) as AdminRefundItem[];
  const totalCount = data?.meta.total ?? 0;

  const TH = (key: string) => (
    <span style={{ fontSize: 10, fontWeight: 800, color: T.textMuted, textTransform: "uppercase", letterSpacing: 0.5 }}>{t(key)}</span>
  );

  const payLabel = (method: string) => t(PAYMENT_I18N_KEYS[method] ?? method);

  const columns: ColumnsType<AdminRefundItem> = [
    {
      title: TH("refunds.colRefundId"),
      key: "rfd_id", width: 130,
      render: (_, row) => (
        <div>
          <div style={{ fontSize: 13, fontWeight: 800, color: T.textDark }}>{refundDisplayId(row.id)}</div>
          <div style={{ fontSize: 11, color: T.textMuted }}>
            {dayjs(row.created_at).format("MMM DD, YYYY")}<br />
            {dayjs(row.created_at).format("h:mm A")}
          </div>
        </div>
      ),
    },
    {
      title: TH("refunds.colTxnId"),
      key: "txn_id", width: 160,
      render: (_, row) => (
        <div
          style={{ cursor: "pointer" }}
          onClick={() => navigate(`/transactions/${row.transaction_id}`)}
        >
          <div style={{ fontSize: 12, fontWeight: 700, color: T.brand, fontFamily: "monospace" }}>
            {txnDisplayId(row.transaction?.reference ?? null, row.transaction_id)}
          </div>
          <div style={{ fontSize: 11, color: T.textMuted }}>
            #{row.order?.order_code ?? "—"}
          </div>
        </div>
      ),
    },
    {
      title: TH("refunds.colCustomerOrder"),
      key: "customer", width: 160,
      render: (_, row) => (
        <div>
          <div style={{ fontSize: 13, fontWeight: 600, color: T.textDark }}>
            {row.order?.customer?.name ?? t("common.guest")}
          </div>
          <div style={{ fontSize: 11, color: T.textMuted }}>
            #{row.order?.order_code ?? "—"}
          </div>
        </div>
      ),
    },
    {
      title: TH("refunds.colAmount"),
      key: "amount", width: 110,
      render: (_, row) => (
        <div>
          <div style={{ fontSize: 15, fontWeight: 800, color: T.textDark }}>
            RM {Number(row.amount).toFixed(2)}
          </div>
          <div style={{ fontSize: 10, color: T.textMuted, marginTop: 2 }}>
            {PAYMENT_I18N_KEYS[row.method] ? payLabel(row.method) : row.method}
          </div>
        </div>
      ),
    },
    {
      title: TH("refunds.colType"),
      key: "type", width: 100,
      render: (_, row) => <TypeBadge type={row.type} />,
    },
    {
      title: TH("refunds.colReason"),
      dataIndex: "reason", key: "reason", width: 140,
      render: (v: string) => <Text style={{ fontSize: 12, color: T.textBody }}>{v}</Text>,
    },
    {
      title: TH("refunds.colStatus"),
      key: "status", width: 130,
      render: (_, row) => <StatusPill status={row.status} />,
    },
    {
      title: TH("refunds.colAction"),
      key: "actions", width: 56, fixed: "right",
      render: (_, row) => {
        const items: MenuProps["items"] = [
          {
            key: "update",
            label: <span style={{ fontSize: 12, fontWeight: 700, letterSpacing: 0.5 }}>{t("refunds.menuUpdateStatus").toUpperCase()}</span>,
            disabled: row.status !== "pending",
            onClick: () => setUpdateTarget(row),
          },
          {
            key: "detail",
            label: <span style={{ fontSize: 12, fontWeight: 700, letterSpacing: 0.5 }}>{t("refunds.menuViewDetails").toUpperCase()}</span>,
            onClick: () => navigate(`/refunds/${row.id}`),
          },
          {
            key: "order",
            label: <span style={{ fontSize: 12, fontWeight: 700, letterSpacing: 0.5 }}>{t("refunds.menuViewOrders").toUpperCase()}</span>,
            onClick: () => navigate(`/orders/${row.order?.id ?? ""}`),
          },
        ];
        return (
          <Dropdown menu={{ items }} trigger={["click"]}>
            <Button type="text" icon={<MoreOutlined />} style={{ padding: "0 8px" }} />
          </Dropdown>
        );
      },
    },
  ];

  // ── Stat cards config ──
  const statCards = [
    {
      label: t("refunds.statTotalAmount").toUpperCase(),
      value: stats ? `RM ${Number(stats.totalAmount).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ",")}` : "—",
      sub: stats ? t("refunds.statSubVsLastMonth") : "",
      subColor: T.successBright,
      icon: <DollarOutlined />,
      iconBg: T.brandLight, iconColor: T.brand,
    },
    {
      label: t("refunds.statTotalCount").toUpperCase(),
      value: stats ? String(stats.totalCount) : "—",
      sub: t("refunds.statAccumulatedMonth"),
      subColor: T.textMuted,
      icon: <FileTextOutlined />,
      iconBg: T.surfaceSection, iconColor: T.textBody,
    },
    {
      label: t("refunds.statPartialCount").toUpperCase(),
      value: stats ? String(stats.partialCount) : "—",
      sub: stats && stats.totalCount > 0
        ? t("refunds.statPartialPct", { pct: Math.round(stats.partialCount / stats.totalCount * 100) })
        : "",
      subColor: T.textMuted,
      icon: <PieChartOutlined />,
      iconBg: T.surfaceGreen, iconColor: T.successBright,
    },
    {
      label: t("refunds.statTodayAmount").toUpperCase(),
      value: stats ? `RM ${Number(stats.todayAmount).toFixed(2)}` : "—",
      sub: t("refunds.statUpdatedNow"),
      subColor: T.textMuted,
      icon: <ClockCircleOutlined />,
      iconBg: T.surfaceBlue, iconColor: T.infoText,
    },
  ];

  return (
    <AdminShell>
      <div style={{ padding: "28px 32px", background: T.bg, minHeight: "100vh" }}>

        {/* Title */}
        <div style={{ fontSize: 26, fontWeight: 800, color: T.textDark, marginBottom: 24 }}>{t("refunds.pageHeading")}</div>

        {/* Stat cards */}
        <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 16, marginBottom: 28 }}>
          {statCards.map((card) => (
            <div
              key={card.label}
              style={{ background: T.surface, borderRadius: 12, border: "1px solid #E5E7EB", padding: "20px 24px" }}
            >
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                <div style={{ fontSize: 10, fontWeight: 800, color: T.textMuted, letterSpacing: 0.8, textTransform: "uppercase", marginBottom: 12, flex: 1 }}>
                  {card.label}
                </div>
                <div style={{ background: card.iconBg, borderRadius: 8, padding: 8, color: card.iconColor, fontSize: 18 }}>
                  {card.icon}
                </div>
              </div>
              <div style={{ fontSize: 28, fontWeight: 900, color: T.textDark, lineHeight: 1.1, marginBottom: 8 }}>
                {card.value}
              </div>
              {card.sub && (
                <div style={{ fontSize: 12, color: card.subColor, display: "flex", alignItems: "center", gap: 4 }}>
                  {card.subColor === T.successBright && <RiseOutlined />}
                  {card.sub}
                </div>
              )}
            </div>
          ))}
        </div>

        {/* Filter bar */}
        <div style={{ background: T.surface, borderRadius: 12, border: "1px solid #E5E7EB", padding: "16px 20px", marginBottom: 20 }}>
          <div style={{ display: "flex", gap: 20, flexWrap: "wrap", alignItems: "flex-end" }}>
            <div>
              <div style={{ fontSize: 11, fontWeight: 700, color: T.textBody, marginBottom: 6 }}>{t("refunds.dateRange").toUpperCase()}</div>
              <RangePicker
                style={{ height: 40 }}
                onChange={(_, s) => {
                  const [from, to] = s as [string, string];
                  setDateRange(from && to ? [
                    dayjs(from).startOf("day").toISOString(),
                    dayjs(to).endOf("day").toISOString(),
                  ] : null);
                  setPage(1);
                }}
              />
            </div>
            <div>
              <div style={{ fontSize: 11, fontWeight: 700, color: T.textBody, marginBottom: 6 }}>{t("refunds.refundType").toUpperCase()}</div>
              <Select
                value={type}
                onChange={(v) => { setType(v as string | undefined); setPage(1); }}
                allowClear
                style={{ width: 140, height: 40 }}
                placeholder={t("refunds.placeholderAllTypes")}
                options={[
                  { value: "full", label: t("refunds.typeFull") },
                  { value: "partial", label: t("refunds.typePartial") },
                ]}
              />
            </div>
            <div>
              <div style={{ fontSize: 11, fontWeight: 700, color: T.textBody, marginBottom: 6 }}>{t("refunds.paymentMethod").toUpperCase()}</div>
              <Select
                value={method}
                onChange={(v) => { setMethod(v as string | undefined); setPage(1); }}
                allowClear
                style={{ width: 160, height: 40 }}
                placeholder={t("refunds.placeholderAllMethods")}
                options={Object.keys(PAYMENT_I18N_KEYS).map((v) => ({ value: v, label: payLabel(v) }))}
              />
            </div>
            <div>
              <div style={{ fontSize: 11, fontWeight: 700, color: T.textBody, marginBottom: 6 }}>{t("refunds.status").toUpperCase()}</div>
              <Select
                value={status}
                onChange={(v) => { setStatus(v as string | undefined); setPage(1); }}
                allowClear
                style={{ width: 140, height: 40 }}
                placeholder={t("refunds.placeholderAllStatus")}
                options={[
                  { value: "pending", label: t("refunds.statusPending") },
                  { value: "success", label: t("refunds.statusSuccess") },
                  { value: "rejected", label: t("refunds.statusRejectedPill") },
                  { value: "failed", label: t("refunds.statusFailed") },
                ]}
              />
            </div>
            <div style={{ flex: 1 }}>
              <div style={{ fontSize: 11, fontWeight: 700, color: T.textBody, marginBottom: 6 }}>{t("refunds.quickSearch").toUpperCase()}</div>
              <Input
                prefix={<SearchOutlined style={{ color: T.textMuted }} />}
                placeholder={t("refunds.placeholderSearch")}
                value={search}
                onChange={(e) => { setSearch(e.target.value); setPage(1); }}
                style={{ height: 40, borderRadius: 8 }}
                allowClear
              />
            </div>
          </div>
        </div>

        {/* Table */}
        <div style={{ background: T.surface, borderRadius: 12, border: "1px solid #E5E7EB", overflow: "hidden" }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "16px 20px", borderBottom: "1px solid #F3F4F6" }}>
            <div style={{ fontSize: 16, fontWeight: 700, color: T.textDark }}>{t("refunds.recentRecords")}</div>
            <Button icon={<DownloadOutlined />} style={{ borderRadius: 8, color: T.successBright, borderColor: "#BBF7D0" }}>
              {t("refunds.exportCsv")}
            </Button>
          </div>
          <DataTable<AdminRefundItem>
            columns={columns}
            dataSource={refunds}
            loading={isLoading}
            pagination={{ current: page, total: totalCount, pageSize: 20, onChange: (p) => setPage(p) }}
          />
        </div>

      </div>

      {updateTarget && (
        <UpdateStatusModal
          refund={updateTarget}
          onClose={() => setUpdateTarget(null)}
        />
      )}
    </AdminShell>
  );
}

