import { BrowserRouter, Routes, Route, Navigate } from "react-router-dom";
import { useEffect, useState, type ReactNode } from "react";
import { ConfigProvider, App as AntdApp } from "antd";
import enUS from "antd/locale/en_US";
import zhCN from "antd/locale/zh_CN";
import i18n from "./i18n";
import { useAuthStore } from "./store/auth";
import { SocketProvider } from "./socket/provider";
import { kawkawTheme } from "./styles/theme";
import { usePermissions } from "./hooks/usePermissions";

import { LoginScreen } from "./screens/Login";
import { DashboardScreen } from "./screens/Dashboard";
import { OrdersScreen } from "./screens/Orders";
import { OrderDetailScreen } from "./screens/OrderDetail";
import { TransactionsScreen } from "./screens/Transactions";
import { TransactionDetailScreen } from "./screens/TransactionDetail";
import { IssueRefundScreen } from "./screens/IssueRefund";
import { RefundsScreen } from "./screens/Refunds";
import { RefundDetailScreen } from "./screens/RefundDetail";
import { MenuScreen } from "./screens/Menu";
import { AddMenuItemScreen } from "./screens/AddMenuItemScreen";
import { VouchersScreen } from "./screens/Vouchers";
import { StaffScreen } from "./screens/Staff";
import { ReportsScreen } from "./screens/Reports";
import { ActivityLogScreen } from "./screens/ActivityLog";
import { FeatureFlagsScreen } from "./screens/FeatureFlags";
import { HoursScreen } from "./screens/Hours";
import { SettingsScreen } from "./screens/Settings";
import { BundlesScreen } from "./screens/Bundles";
import { StallsScreen } from "./screens/Stalls";
import { StallApplicationsScreen } from "./screens/StallApplications";
import { PaymentMethodsScreen } from "./screens/PaymentMethods";
import { DeliveryProvidersScreen } from "./screens/DeliveryProviders";
import { BannersScreen } from "./screens/Banners";
import { CategoriesScreen } from "./screens/Categories";

function Protected({ children, routePath }: { children: ReactNode; routePath?: string }) {
  const token = useAuthStore((s) => s.accessToken);
  const { canRoute } = usePermissions();
  if (!token) return <Navigate to="/login" replace />;
  // If a routePath is provided, check RBAC — redirect to "/" if not allowed
  if (routePath && !canRoute(routePath)) return <Navigate to="/" replace />;
  return <>{children}</>;
}

function AppWithAntdLocale({ children }: { children: ReactNode }) {
  const [lang, setLang] = useState(i18n.language);
  useEffect(() => {
    const onChange = () => setLang(i18n.language);
    i18n.on("languageChanged", onChange);
    return () => {
      i18n.off("languageChanged", onChange);
    };
  }, []);
  const locale = lang?.startsWith("zh") ? zhCN : enUS;
  return (
    <ConfigProvider locale={locale} theme={kawkawTheme}>
      {children}
    </ConfigProvider>
  );
}

export function App() {
  return (
    <AppWithAntdLocale>
      <AntdApp>
      <BrowserRouter basename={import.meta.env.BASE_URL} future={{ v7_relativeSplatPath: true, v7_startTransition: true }}>
        <SocketProvider>
          <Routes>
            <Route path="/login" element={<LoginScreen />} />
            <Route path="/" element={<Protected routePath="/"><DashboardScreen /></Protected>} />
            <Route path="/orders" element={<Protected routePath="/orders"><OrdersScreen /></Protected>} />
            <Route path="/orders/:id" element={<Protected routePath="/orders"><OrderDetailScreen /></Protected>} />
            <Route path="/transactions" element={<Protected routePath="/transactions"><TransactionsScreen /></Protected>} />
            <Route path="/transactions/:id" element={<Protected routePath="/transactions"><TransactionDetailScreen /></Protected>} />
            <Route path="/transactions/:id/refund" element={<Protected routePath="/transactions"><IssueRefundScreen /></Protected>} />
            <Route path="/refunds" element={<Protected routePath="/refunds"><RefundsScreen /></Protected>} />
            <Route path="/refunds/:id" element={<Protected routePath="/refunds"><RefundDetailScreen /></Protected>} />
            <Route path="/menu" element={<Protected routePath="/menu"><MenuScreen /></Protected>} />
            <Route path="/menu/items/new" element={<Protected routePath="/menu"><AddMenuItemScreen /></Protected>} />
            <Route path="/categories" element={<Protected routePath="/categories"><CategoriesScreen /></Protected>} />
            <Route path="/vouchers" element={<Protected routePath="/vouchers"><VouchersScreen /></Protected>} />
            <Route path="/staff" element={<Protected routePath="/staff"><StaffScreen /></Protected>} />
            <Route path="/reports" element={<Protected routePath="/reports"><ReportsScreen /></Protected>} />
            <Route path="/activity" element={<Protected routePath="/activity"><ActivityLogScreen /></Protected>} />
            <Route path="/flags" element={<Protected routePath="/flags"><FeatureFlagsScreen /></Protected>} />
            <Route path="/hours" element={<Protected routePath="/hours"><HoursScreen /></Protected>} />
            <Route path="/settings" element={<Protected routePath="/settings"><SettingsScreen /></Protected>} />
            <Route path="/bundles" element={<Protected routePath="/bundles"><BundlesScreen /></Protected>} />
            <Route path="/stalls" element={<Protected routePath="/stalls"><StallsScreen /></Protected>} />
            <Route path="/stall-applications" element={<Protected routePath="/stall-applications"><StallApplicationsScreen /></Protected>} />
            <Route path="/payment-methods" element={<Protected routePath="/payment-methods"><PaymentMethodsScreen /></Protected>} />
            <Route path="/delivery-providers" element={<Protected routePath="/delivery-providers"><DeliveryProvidersScreen /></Protected>} />
            <Route path="/banners" element={<Protected routePath="/banners"><BannersScreen /></Protected>} />
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </SocketProvider>
      </BrowserRouter>
      </AntdApp>
    </AppWithAntdLocale>
  );
}
