import { Layout, Menu, Avatar, Dropdown, Typography, Badge, Input, ConfigProvider } from "antd";
import {
  DashboardOutlined, ShoppingOutlined, CreditCardOutlined,
  RollbackOutlined, AppstoreOutlined, TagsOutlined, TeamOutlined,
  BarChartOutlined, SettingOutlined, HistoryOutlined, FlagOutlined,
  ClockCircleOutlined, LogoutOutlined, UserOutlined,
  GiftOutlined, ShopOutlined, WalletOutlined, CarOutlined, PictureOutlined, AppstoreAddOutlined,
  SearchOutlined, BellOutlined, AppstoreFilled,
} from "@ant-design/icons";
import { useNavigate, useLocation } from "react-router-dom";
import type { ReactNode } from "react";
import { useTranslation } from "react-i18next";
import { useAuthStore } from "../store/auth";
import { usePermissions } from "../hooks/usePermissions";

const { Sider, Header, Content } = Layout;
const { Text } = Typography;

const SIDEBAR_W = 220;

export function AdminShell({ children }: { children: ReactNode }) {
  const navigate = useNavigate();
  const location = useLocation();
  const staff = useAuthStore((s) => s.staff);
  const logout = useAuthStore((s) => s.logout);
  const { t, i18n } = useTranslation();
  const { canRoute } = usePermissions();

  const ALL_NAV_ITEMS = [
    { key: "/", icon: <DashboardOutlined />, label: t("nav.dashboard") },
    { key: "/orders", icon: <ShoppingOutlined />, label: t("nav.orders") },
    { key: "/transactions", icon: <CreditCardOutlined />, label: t("nav.transactions") },
    { key: "/refunds", icon: <RollbackOutlined />, label: t("nav.refunds") },
    { key: "/menu", icon: <AppstoreOutlined />, label: t("nav.menu") },
    { key: "/categories", icon: <AppstoreAddOutlined />, label: t("nav.categories") },
    { key: "/vouchers", icon: <TagsOutlined />, label: t("nav.vouchers") },
    { key: "/bundles", icon: <GiftOutlined />, label: t("nav.bundles") },
    { key: "/stalls", icon: <ShopOutlined />, label: t("nav.stalls") },
    { key: "/stall-applications", icon: <ShopOutlined />, label: t("nav.stallApplications") },
    { key: "/payment-methods", icon: <WalletOutlined />, label: t("nav.paymentMethods") },
    { key: "/delivery-providers", icon: <CarOutlined />, label: t("nav.deliveryProviders") },
    { key: "/banners", icon: <PictureOutlined />, label: t("nav.banners") },
    { key: "/staff", icon: <TeamOutlined />, label: t("nav.staff") },
    { key: "/reports", icon: <BarChartOutlined />, label: t("nav.reports") },
    { key: "/activity", icon: <HistoryOutlined />, label: t("nav.activity") },
    { key: "/flags", icon: <FlagOutlined />, label: t("nav.flags") },
    { key: "/hours", icon: <ClockCircleOutlined />, label: t("nav.hours") },
  ];

  const SETTINGS_ITEM = [
    { key: "/settings", icon: <SettingOutlined />, label: t("nav.settings") },
  ];

  const NAV_ITEMS = ALL_NAV_ITEMS.filter((item) => canRoute(item.key));
  const canSettings = canRoute("/settings");

  const toggleLang = () => {
    const next = i18n.language === "zh" ? "en" : "zh";
    void i18n.changeLanguage(next);
    localStorage.setItem("kawkaw_admin_lang", next);
  };

  const userMenu = {
    items: [
      {
        key: "lang",
        icon: <span style={{ fontSize: 14 }}>🌐</span>,
        label: i18n.language === "zh" ? t("common.switchLangEn") : t("common.switchLangZh"),
        onClick: toggleLang,
      },
      {
        key: "logout",
        icon: <LogoutOutlined />,
        label: t("common.signOut"),
        danger: true,
        onClick: () => { logout(); void navigate("/login"); },
      },
    ],
  };

  return (
    <Layout style={{ minHeight: "100vh" }}>
      {/* ── Sidebar ─────────────────────────────────────────── */}
      <ConfigProvider
        theme={{
          components: {
            Menu: {
              itemSelectedColor: "#F97316",
              itemSelectedBg: "#FFF7ED",
              itemHoverBg: "#FFF7ED",
              itemHoverColor: "#F97316",
            },
          },
        }}
      >
        <Sider
          width={SIDEBAR_W}
          theme="light"
          style={{
            position: "fixed", insetBlockStart: 0, insetInlineStart: 0,
            height: "100vh", zIndex: 100,
            background: "#fff",
            borderRight: "1px solid #F3F4F6",
            display: "flex", flexDirection: "column",
          }}
        >
          {/* Logo */}
          <div style={{
            height: 64, display: "flex", alignItems: "center",
            padding: "0 16px", gap: 10, flexShrink: 0,
            borderBottom: "1px solid #F3F4F6",
          }}>
            <div style={{
              width: 38, height: 38, borderRadius: 10, background: "#F97316",
              display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0,
            }}>
              <AppstoreFilled style={{ color: "#fff", fontSize: 20 }} />
            </div>
            <div style={{ lineHeight: 1.3 }}>
              <Text strong style={{ fontSize: 14, color: "#111827", display: "block" }}>{t("nav.brandTitle")}</Text>
              <Text style={{ fontSize: 11, color: "#9CA3AF" }}>{t("nav.brandSubtitle")}</Text>
            </div>
          </div>

          {/* Nav list + Settings pinned at bottom */}
          <div style={{ display: "flex", flexDirection: "column", flex: 1, overflow: "hidden" }}>
            <div style={{ flex: 1, overflowY: "auto" }}>
              <Menu
                mode="inline"
                selectedKeys={[location.pathname]}
                items={NAV_ITEMS}
                onClick={({ key }) => void navigate(key)}
                style={{ borderRight: 0, paddingTop: 8 }}
              />
            </div>
            {canSettings && (
              <div style={{ borderTop: "1px solid #F3F4F6", flexShrink: 0 }}>
                <Menu
                  mode="inline"
                  selectedKeys={[location.pathname]}
                  items={SETTINGS_ITEM}
                  onClick={({ key }) => void navigate(key)}
                  style={{ borderRight: 0 }}
                />
              </div>
            )}
          </div>
        </Sider>
      </ConfigProvider>

      {/* ── Main ────────────────────────────────────────────── */}
      <Layout style={{ marginInlineStart: SIDEBAR_W }}>
        <Header style={{
          position: "sticky", top: 0, zIndex: 99,
          background: "#fff", padding: "0 24px",
          display: "flex", alignItems: "center", gap: 16,
          borderBottom: "1px solid #F3F4F6", height: 64,
          boxShadow: "0 1px 3px rgba(0,0,0,0.04)",
        }}>
          {/* Search */}
          <Input
            prefix={<SearchOutlined style={{ color: "#9CA3AF" }} />}
            placeholder={t("common.search")}
            variant="filled"
            style={{ flex: 1, maxWidth: 380, borderRadius: 8 }}
          />

          {/* Right controls */}
          <div style={{ marginLeft: "auto", display: "flex", alignItems: "center", gap: 20 }}>
            <Badge count={0} showZero={false}>
              <BellOutlined style={{ fontSize: 20, color: "#374151", cursor: "pointer" }} />
            </Badge>

            <Dropdown menu={userMenu} placement="bottomRight" arrow>
              <div style={{ display: "flex", alignItems: "center", gap: 10, cursor: "pointer" }}>
                <div style={{ lineHeight: 1.3, textAlign: "right" }}>
                  <Text strong style={{ fontSize: 13, display: "block", color: "#111827" }}>
                    {staff?.name ?? t("staff.admin")}
                  </Text>
                  <Text style={{
                    fontSize: 10, color: "#0D9488",
                    textTransform: "uppercase", fontWeight: 700,
                    letterSpacing: 0.5, display: "block",
                  }}>
                    {staff?.role ?? ""}
                  </Text>
                </div>
                <Avatar icon={<UserOutlined />} size={36} style={{ background: "#F97316" }} />
              </div>
            </Dropdown>
          </div>
        </Header>

        <Content style={{ padding: 24, minHeight: "calc(100vh - 64px)", background: "#F9FAFB" }}>
          {children}
        </Content>
      </Layout>
    </Layout>
  );
}
