import { useState, useMemo } from "react";
import { useTranslation } from "react-i18next";
import {
  Button, Checkbox, Input, InputNumber, Select, Spin, App, Divider, Typography,
} from "antd";
import {
  ArrowLeftOutlined,
  SafetyCertificateOutlined,
  WarningFilled,
  InfoCircleOutlined,
  AlignLeftOutlined,
  CreditCardOutlined,
} from "@ant-design/icons";
import { useNavigate, useParams } from "react-router-dom";
import { formatDateTimeDetail } from "../utils/formatLocaleDate";
import { AdminShell } from "../layouts/AdminShell";
import { tokens } from "../styles/tokens";
const { color: T } = tokens;
import { useAdminTransaction, useInitiateRefund } from "../api/hooks";

const { Text } = Typography;

const ISSUE_PAYMENT_I18N: Record<string, { title: string; desc: string }> = {
  visa:    { title: "issueRefund.payVisa",    desc: "issueRefund.descVisa" },
  fpx:     { title: "issueRefund.payFpx",     desc: "issueRefund.descFpx" },
  grabpay: { title: "issueRefund.payGrab",    desc: "issueRefund.descGrab" },
  cash:    { title: "issueRefund.payCash",    desc: "issueRefund.descCash" },
  ewallet: { title: "issueRefund.payEwallet", desc: "issueRefund.descEwallet" },
  tng:     { title: "issueRefund.payTng",     desc: "issueRefund.descTng" },
  boost:   { title: "issueRefund.payBoost",   desc: "issueRefund.descBoost" },
};

export function IssueRefundScreen() {
  const { t, i18n } = useTranslation();
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { message } = App.useApp();

  const reasonOptions = useMemo(
    () => [
      { value: "Customer Cancelled", label: t("issueRefund.reasonCustomerCancelled") },
      { value: "Out of stock", label: t("issueRefund.reasonOutOfStock") },
      { value: "Wrong item", label: t("issueRefund.reasonWrongItem") },
      { value: "Duplicate payment", label: t("issueRefund.reasonDuplicate") },
      { value: "Order not delivered", label: t("issueRefund.reasonNotDelivered") },
      { value: "Quality issue", label: t("issueRefund.reasonQuality") },
      { value: "Other", label: t("issueRefund.reasonOther") },
    ],
    [t],
  );

  const { data: txn, isLoading } = useAdminTransaction(id);
  const initiateRefund = useInitiateRefund();

  const [refundType, setRefundType] = useState<"full" | "partial">("full");
  const [partialAmount, setPartialAmount] = useState<number | null>(null);
  const [reason, setReason] = useState<string | null>(null);
  const [internalNote, setInternalNote] = useState("");
  const [confirmed, setConfirmed] = useState(false);

  const txnTotal = txn ? Number(txn.amount) : 0;
  const refundAmount = refundType === "full" ? txnTotal : (partialAmount ?? 0);

  const canSubmit = !!reason && confirmed && refundAmount > 0 && !!txn?.order?.id;

  const onSubmit = async () => {
    if (!txn?.order?.id || !reason) return;
    try {
      await initiateRefund.mutateAsync({
        orderId: txn.order.id,
        amount: refundAmount.toFixed(2),
        type: refundType,
        reason,
        method: txn.method,
      });
      void message.success(t("issueRefund.success"));
      navigate(`/transactions/${id ?? ""}`);
    } catch {
      void message.error(t("issueRefund.failed"));
    }
  };

  if (isLoading) {
    return (
      <AdminShell>
        <div style={{ display: "flex", justifyContent: "center", alignItems: "center", minHeight: 300 }}>
          <Spin size="large" />
        </div>
      </AdminShell>
    );
  }

  if (!txn) {
    return (
      <AdminShell>
        <div style={{ padding: 40, textAlign: "center", color: "#9CA3AF" }}>{t("issueRefund.notFound")}</div>
      </AdminShell>
    );
  }

  const order = txn.order;
  const txnDisplayCode = txn.reference?.toUpperCase() ?? `TXN-${txn.id.slice(0, 12).toUpperCase()}`;
  const payCopy = ISSUE_PAYMENT_I18N[txn.method] ?? null;
  const payTitle = payCopy ? t(payCopy.title) : txn.method.toUpperCase();
  const payDesc = payCopy ? t(payCopy.desc) : t("issueRefund.methodDescFallback");

  return (
    <AdminShell>
      <div style={{ background: T.bg, minHeight: "100vh", padding: "28px 32px" }}>

        {/* ── Page title / meta ── */}
        <div style={{ marginBottom: 28 }}>
          <div style={{ fontSize: 30, fontWeight: 800, color: T.textDark, marginBottom: 8 }}>{t("issueRefund.title")}</div>
          <div style={{ display: "flex", alignItems: "center", gap: 20, fontSize: 13, color: T.textBody, flexWrap: "wrap" }}>
            <span>{t("issueRefund.txnId")} <Text copyable style={{ fontFamily: "monospace", fontWeight: 600, color: T.textDark }}>{txnDisplayCode}</Text></span>
            {order && (
              <span>
                {t("issueRefund.orderId")}{" "}
                <span
                  style={{ color: T.brand, fontWeight: 700, cursor: "pointer" }}
                  onClick={() => navigate(`/orders/${order.id}`)}
                >
                  #{order.order_code}
                </span>
              </span>
            )}
            <span>{t("issueRefund.datePaid")} {formatDateTimeDetail(txn.paid_at ?? txn.created_at, i18n.language)}</span>
            <button
              onClick={() => navigate(-1)}
              style={{ background: "none", border: "none", cursor: "pointer", color: T.textMuted, display: "flex", alignItems: "center", gap: 4, padding: 0, fontSize: 13 }}
            >
              <ArrowLeftOutlined /> {t("issueRefund.back")}
            </button>
          </div>
        </div>

        {/* ── Two-column layout ── */}
        <div style={{ display: "flex", gap: 24, alignItems: "flex-start" }}>

          {/* ── Left column ── */}
          <div style={{ flex: 1, minWidth: 0, display: "flex", flexDirection: "column", gap: 20 }}>

            {/* REFUND TYPE */}
            <div style={{ background: T.surface, borderRadius: 16, padding: "24px 28px", border: "1px solid #E5E7EB" }}>
              <SectionHeader icon="↺" label={t("issueRefund.sectionRefundType")} />
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16, marginTop: 16 }}>

                {/* Full Refund card */}
                <div
                  onClick={() => setRefundType("full")}
                  style={{
                    borderRadius: 12, border: `2px solid ${refundType === "full" ? T.brand : T.border}`,
                    padding: "18px 20px", cursor: "pointer", transition: "border-color 0.15s",
                    background: refundType === "full" ? T.brandFaint : T.surface, position: "relative",
                  }}
                >
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                    <div style={{ fontSize: 15, fontWeight: 700, color: T.textDark, marginBottom: 8 }}>{t("issueRefund.fullRefund")}</div>
                    <RadioDot selected={refundType === "full"} />
                  </div>
                  <div style={{ fontSize: 13, color: T.textBody, lineHeight: 1.5 }}>
                    {t("issueRefund.fullRefundDesc", { amount: txnTotal.toFixed(2) })}
                  </div>
                </div>

                {/* Partial Refund card */}
                <div
                  onClick={() => setRefundType("partial")}
                  style={{
                    borderRadius: 12, border: `2px solid ${refundType === "partial" ? T.brand : T.border}`,
                    padding: "18px 20px", cursor: "pointer", transition: "border-color 0.15s",
                    background: refundType === "partial" ? T.brandFaint : T.surface,
                  }}
                >
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                    <div style={{ fontSize: 15, fontWeight: 700, color: T.textDark, marginBottom: 8 }}>{t("issueRefund.partialRefund")}</div>
                    <RadioDot selected={refundType === "partial"} />
                  </div>
                  <div style={{ fontSize: 13, color: T.textBody, lineHeight: 1.5, marginBottom: 12 }}>
                    {t("issueRefund.partialDesc")}
                  </div>
                  {refundType === "partial" && (
                    <>
                      <InputNumber
                        prefix="RM"
                        min={0.01}
                        max={txnTotal}
                        precision={2}
                        placeholder="0.00"
                        style={{ width: "100%", borderRadius: 8 }}
                        value={partialAmount}
                        onChange={v => setPartialAmount(v)}
                        onClick={e => e.stopPropagation()}
                      />
                      <div style={{ fontSize: 11, color: T.textMuted, marginTop: 6 }}>
                        {t("issueRefund.maxRefundable", { amount: txnTotal.toFixed(2) })}
                      </div>
                    </>
                  )}
                </div>
              </div>
            </div>

            {/* REFUND BREAKDOWN */}
            {order && (
              <div style={{ background: T.surface, borderRadius: 16, padding: "24px 28px", border: "1px solid #E5E7EB" }}>
                <SectionHeader icon="≡" label={t("issueRefund.sectionBreakdown")} />
                <div style={{ display: "flex", flexDirection: "column", gap: 14, marginTop: 20 }}>
                  {refundType === "full" ? (
                    <>
                      <BreakdownRow label={t("issueRefund.foodBev")} amount={Number(order.subtotal)} />
                      {Number(order.delivery_fee) > 0 && <BreakdownRow label={t("issueRefund.deliveryFee")} amount={Number(order.delivery_fee)} />}
                      {Number(order.sst_amount) > 0 && <BreakdownRow label={t("issueRefund.sst")} amount={Number(order.sst_amount)} />}
                      {order.voucher_code && Number(order.voucher_discount) > 0 && (
                        <div style={{ display: "flex", justifyContent: "space-between" }}>
                          <span style={{ fontSize: 14, color: T.successBright }}>{t("issueRefund.appliedDiscount")}</span>
                          <span style={{ fontSize: 14, fontWeight: 600, color: T.successBright }}>
                            −RM {Number(order.voucher_discount).toFixed(2)}
                          </span>
                        </div>
                      )}
                    </>
                  ) : (
                    <BreakdownRow label={t("issueRefund.refundAmountRow")} amount={partialAmount ?? 0} />
                  )}
                </div>
                <Divider style={{ margin: "20px 0" }} />
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                  <span style={{ fontSize: 15, fontWeight: 700, color: T.textDark }}>{t("issueRefund.totalRefundAmount")}</span>
                  <span style={{ fontSize: 18, fontWeight: 800, color: T.textDark }}>
                    RM {refundAmount.toFixed(2)}
                  </span>
                </div>
              </div>
            )}

            {/* REASON & DOCUMENTATION */}
            <div style={{ background: T.surface, borderRadius: 16, padding: "24px 28px", border: "1px solid #E5E7EB" }}>
              <SectionHeader icon={<AlignLeftOutlined style={{ fontSize: 13 }} />} label={t("issueRefund.sectionReason")} />
              <div style={{ marginTop: 20, display: "flex", flexDirection: "column", gap: 16 }}>
                <div>
                  <div style={{ fontSize: 11, fontWeight: 700, color: T.textMuted, letterSpacing: 0.8, marginBottom: 8 }}>
                    {t("issueRefund.refundReasonLabel")}
                  </div>
                  <Select
                    style={{ width: "100%" }}
                    placeholder={t("issueRefund.reasonPlaceholder")}
                    value={reason}
                    onChange={setReason}
                    options={reasonOptions}
                  />
                </div>
                <div>
                  <div style={{ fontSize: 11, fontWeight: 700, color: T.textMuted, letterSpacing: 0.8, marginBottom: 8 }}>
                    {t("issueRefund.internalNote")}{" "}
                    <span style={{ fontWeight: 400, color: T.borderLight }}>{t("issueRefund.internalOptional")}</span>
                  </div>
                  <Input.TextArea
                    rows={4}
                    placeholder={t("issueRefund.internalPlaceholder")}
                    value={internalNote}
                    onChange={e => setInternalNote(e.target.value)}
                    style={{ borderRadius: 8, resize: "none" }}
                  />
                </div>
              </div>
            </div>

            {/* REFUND METHOD */}
            <div style={{ background: T.surface, borderRadius: 16, padding: "24px 28px", border: "1px solid #E5E7EB" }}>
              <SectionHeader icon={<CreditCardOutlined style={{ fontSize: 13 }} />} label={t("issueRefund.sectionMethod")} />
              <div style={{ marginTop: 16 }}>
                <div style={{
                  display: "flex", alignItems: "center", gap: 14,
                  background: T.bg, borderRadius: 12, padding: "16px 20px",
                  border: "1px solid #E5E7EB",
                }}>
                  <div style={{
                    width: 44, height: 44, borderRadius: "50%", flexShrink: 0,
                    background: T.successDeep, display: "flex", alignItems: "center", justifyContent: "center",
                  }}>
                    <SafetyCertificateOutlined style={{ color: T.surface, fontSize: 20 }} />
                  </div>
                  <div>
                    <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
                      <span style={{ fontSize: 14, fontWeight: 700, color: T.textDark }}>
                        {payTitle}
                      </span>
                      <div style={{ width: 8, height: 8, borderRadius: "50%", background: T.successBright }} />
                    </div>
                    <div style={{ fontSize: 12, color: T.textBody, lineHeight: 1.5 }}>
                      {payDesc}
                    </div>
                  </div>
                </div>
              </div>
            </div>

          </div>

          {/* ── Right sidebar ── */}
          <div style={{ width: 280, flexShrink: 0, display: "flex", flexDirection: "column", gap: 16 }}>

            {/* Original paid amount */}
            <div style={{ background: T.surface, borderRadius: 16, padding: "20px", border: "1px solid #E5E7EB", textAlign: "right" }}>
              <div style={{ fontSize: 11, fontWeight: 700, color: T.textMuted, letterSpacing: 0.8, marginBottom: 8, textTransform: "uppercase" }}>
                {t("issueRefund.originalPaid")}
              </div>
              <div style={{ fontSize: 26, fontWeight: 800, color: T.textDark }}>
                RM {txnTotal.toFixed(2)}
              </div>
            </div>

            {/* Settlement summary card */}
            <div style={{ background: T.receiptBg, borderRadius: 16, padding: "24px", display: "flex", flexDirection: "column", gap: 16 }}>
              <div style={{ fontSize: 11, fontWeight: 700, color: T.textMuted, letterSpacing: 0.8, textTransform: "uppercase" }}>
                {t("issueRefund.settlementSummary")}
              </div>
              <div style={{ fontSize: 28, fontWeight: 800, color: T.surface }}>
                RM {refundAmount > 0 ? refundAmount.toFixed(2) : "0.00"}
              </div>

              {/* Warning box */}
              <div style={{
                background: "#3B1A1A", border: "1px solid #7F1D1D", borderRadius: 10,
                padding: "12px 14px", display: "flex", alignItems: "flex-start", gap: 10,
              }}>
                <WarningFilled style={{ color: "#F87171", fontSize: 14, marginTop: 1, flexShrink: 0 }} />
                <div style={{ fontSize: 12, color: "#FCA5A5", lineHeight: 1.5 }}>
                  {t("issueRefund.warningIrreversible")}
                </div>
              </div>

              {/* Confirm checkbox */}
              <div style={{ display: "flex", alignItems: "flex-start", gap: 10 }}>
                <Checkbox
                  checked={confirmed}
                  onChange={e => setConfirmed(e.target.checked)}
                  style={{ marginTop: 1 }}
                />
                <span style={{ fontSize: 12, color: T.borderLight, lineHeight: 1.6, cursor: "pointer" }} onClick={() => setConfirmed(v => !v)}>
                  {t("issueRefund.confirmCheckbox")}
                </span>
              </div>

              {/* Confirm button */}
              <Button
                block
                type="primary"
                loading={initiateRefund.isPending}
                disabled={!canSubmit}
                onClick={() => void onSubmit()}
                style={{
                  background: canSubmit ? T.dangerText : T.textSecondary,
                  borderColor: canSubmit ? T.dangerText : T.textSecondary,
                  borderRadius: 10, height: 48,
                  fontSize: 15, fontWeight: 700, letterSpacing: 0.3,
                }}
              >
                {t("issueRefund.confirmRefund")}
              </Button>

              {/* Cancel link */}
              <div style={{ textAlign: "center" }}>
                <button
                  onClick={() => navigate(-1)}
                  style={{ background: "none", border: "none", cursor: "pointer", fontSize: 13, color: T.textMuted, textDecoration: "underline" }}
                >
                  {t("issueRefund.cancelReturn")}
                </button>
              </div>

              {/* Merchant info */}
              {order && (
                <div style={{ paddingTop: 8, borderTop: "1px solid #2D2D2D", fontSize: 11, color: "#4B5563", lineHeight: 1.8 }}>
                  <div>{t("issueRefund.merchantId")} KPI-{txn.id.slice(0, 7).toUpperCase()}</div>
                  <div>{t("issueRefund.authorizedBy")} {t("issueRefund.roleAdmin")}</div>
                </div>
              )}
            </div>

            {/* Partial refund tip */}
            {refundType === "partial" && (
              <div style={{
                background: T.surfaceBlue, borderRadius: 12, padding: "14px 16px",
                border: "1px solid #BFDBFE", display: "flex", alignItems: "flex-start", gap: 10,
              }}>
                <InfoCircleOutlined style={{ color: "#2563EB", fontSize: 14, marginTop: 2, flexShrink: 0 }} />
                <div>
                  <div style={{ fontSize: 12, fontWeight: 700, color: T.infoDeep, marginBottom: 4 }}>{t("issueRefund.partialTipTitle")}</div>
                  <div style={{ fontSize: 12, color: T.infoText, lineHeight: 1.5 }}>
                    {t("issueRefund.partialTipBody")}
                  </div>
                </div>
              </div>
            )}

          </div>
        </div>
      </div>
    </AdminShell>
  );
}

/* ── Helpers ── */

function RadioDot({ selected }: { selected: boolean }) {
  return (
    <div style={{
      width: 18, height: 18, borderRadius: "50%", flexShrink: 0, marginTop: 2,
      border: `2px solid ${selected ? T.brand : T.borderLight}`,
      display: "flex", alignItems: "center", justifyContent: "center",
    }}>
      {selected && <div style={{ width: 8, height: 8, borderRadius: "50%", background: T.brand }} />}
    </div>
  );
}

function SectionHeader({ icon, label }: { icon: React.ReactNode; label: string }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
      <span style={{ fontSize: 14, color: T.textMuted }}>{icon}</span>
      <span style={{ fontSize: 11, fontWeight: 700, color: T.textBody, letterSpacing: 0.8, textTransform: "uppercase" as const }}>
        {label}
      </span>
    </div>
  );
}

function BreakdownRow({ label, amount }: { label: string; amount: number }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between" }}>
      <span style={{ fontSize: 14, color: T.textBody }}>{label}</span>
      <span style={{ fontSize: 14, color: T.textDark, fontWeight: 500 }}>RM {amount.toFixed(2)}</span>
    </div>
  );
}
