// ── Status styles ─────────────────────────────────────────────────────────────
const STATUS_STYLE: Record<string, { bg: string; color: string }> = {
  preparing:        { bg: T.statusPreparingBg, color: T.brand },
  ready:            { bg: T.successText, color: T.surface },
  out_for_delivery: { bg: T.tealBg, color: T.tealDeep },
  in_transit:       { bg: T.surfaceSection, color: T.textSecondary },
  delivered:        { bg: T.successDeep, color: T.surface },
  completed:        { bg: T.successDeep, color: T.surface },
  cancelled:        { bg: T.surfaceSection, color: T.textMuted },
  new:              { bg: T.surfaceYellow, color: T.statusPendingText },
};

function StatusPill({ status, size = "md" }: { status: string; size?: "sm" | "md" }) {
  const { t } = useTranslation();
  const s = STATUS_STYLE[status] ?? { bg: T.surfaceSection, color: T.textMuted };
  const label = t(`orders.status.${status}`, { defaultValue: status.replace(/_/g, " ") });
  return (
    <span style={{
      background: s.bg, color: s.color, borderRadius: 20,
      padding: size === "sm" ? "3px 10px" : "5px 16px",
      fontSize: size === "sm" ? 11 : 12,
      fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.5,
      whiteSpace: "nowrap", display: "inline-block",
    }}>
      {label}
    </span>
  );
}

function TypePill({ type }: { type: string }) {
  const { t } = useTranslation();
  const isDelivery = type === "delivery";
  const label = t(`orders.type.${type}`, { defaultValue: type });
  return (
    <span style={{
      display: "inline-flex", alignItems: "center", gap: 5,
      background: isDelivery ? T.surfaceBlue : T.surfaceGreen,
      color: isDelivery ? T.infoDeep : "#15803D",
      border: `1px solid ${isDelivery ? "#BFDBFE" : "#BBF7D0"}`,
      borderRadius: 20, padding: "5px 14px",
      fontSize: 12, fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.5,
    }}>
      {isDelivery ? <CarOutlined /> : <ShoppingOutlined />}
      {label}
    </span>
  );
}

// ── Contextual status message ─────────────────────────────────────────────────
function statusMessage(od: OrderDetailData, t: TFunction): string {
  switch (od.status) {
    case "new":              return t("orderDetail.statusMsg.new");
    case "preparing":        return t("orderDetail.statusMsg.preparing");
    case "ready":            return od.type === "pickup" ? t("orderDetail.statusMsg.readyPickup") : t("orderDetail.statusMsg.readyDelivery");
    case "out_for_delivery": return t("orderDetail.statusMsg.outForDelivery");
    case "in_transit":       return t("orderDetail.statusMsg.inTransit");
    case "delivered":        return t("orderDetail.statusMsg.delivered");
    case "completed":        return od.type === "pickup" ? t("orderDetail.statusMsg.completedPickup") : t("orderDetail.statusMsg.completedDelivery");
    case "cancelled":        return t("orderDetail.statusMsg.cancelled") + (od.cancel_reason ? `: ${od.cancel_reason}` : "");
    default:                 return "";
  }
}

// ── Journey step builder ──────────────────────────────────────────────────────
const STATUS_IDX: Record<string, number> = {
  new: 0, preparing: 1, ready: 2, out_for_delivery: 3, in_transit: 4,
  delivered: 5, completed: 6, cancelled: 99,
};

interface JStep { label: string; time?: string | null; state: "done" | "active" | "pending"; subtext?: string }

function buildJourney(od: OrderDetailData, t: TFunction): JStep[] {
  const curIdx = STATUS_IDX[od.status] ?? 0;
  const st = (thresholdIdx: number): "done" | "active" | "pending" =>
    curIdx > thresholdIdx ? "done" : curIdx === thresholdIdx ? "active" : "pending";

  const readyLabel = t("orderDetail.journey.ready");
  const base: JStep[] = [
    { label: t("orderDetail.journey.orderCreated"), time: od.created_at,  state: "done" },
    { label: t("orderDetail.journey.accepted"),      time: od.accepted_at, state: curIdx > 0 ? "done" : "pending" },
    { label: t("orderDetail.journey.preparing"),     time: null,            state: st(1) },
    { label: readyLabel,         time: od.ready_at,    state: st(2) },
  ];

  if (od.type === "delivery") {
    return [
      ...base.map(s => s.label === readyLabel && s.state === "pending" ? { ...s, subtext: t("orderDetail.journey.waitingPickup") } : s),
      { label: t("orderDetail.journey.riderAssigned"),   time: od.rider?.assigned_at ?? null, state: st(3) },
      { label: t("orderDetail.journey.riderArrived"),    time: null,                           state: curIdx >= 4 ? "done" : "pending" },
      { label: t("orderDetail.journey.outForDelivery"), time: od.dispatched_at ?? null,       state: st(4) },
      { label: t("orderDetail.journey.delivered"),        time: od.delivered_at ?? null,        state: st(5) },
    ];
  }

  return [
    ...base,
    { label: t("orderDetail.journey.pickedUp"), time: od.completed_at, state: st(6) },
  ];
}

function paymentMethodLabel(t: TFunction, method: string): string {
  const key = `orderDetail.payment.${method}`;
  const tr = t(key);
  return tr === key ? method : tr;
}

