import { useState } from "react";
import type React from "react";
import { useNavigate } from "react-router-dom";
import { Button, Drawer, Descriptions, Typography, Divider, Modal, Form, App, Dropdown, Table, Input } from "antd";
import { CarOutlined, ShoppingOutlined, EllipsisOutlined, PhoneOutlined } from "@ant-design/icons";
import { useTranslation } from "react-i18next";
import type { ColumnsType } from "antd/es/table";
import type { Order, OrderItem } from "@kawkaw/shared";
import dayjs from "dayjs";
import { AdminShell } from "../layouts/AdminShell";
import { tokens } from "../styles/tokens";
const { color: T } = tokens;
import { useAdminOrders, useAdminOrder, useAdminCancelOrder, useAdminUpdateOrderStatus, useDashboardStats } from "../api/hooks";

const { Text } = Typography;

// ── Colors ───────────────────────────────────────────────────────────────────
// ── Status pill ──────────────────────────────────────────────────────────────
const STATUS_STYLE: Record<string, { bg: string; color: string }> = {
  preparing:        { bg: T.statusPreparingBg, color: T.brand },
  ready:            { bg: T.successText, color: T.surface },
  out_for_delivery: { bg: T.tealBg, color: T.tealDeep },
  in_transit:       { bg: T.surfaceSection, color: T.textSecondary },
  delivered:        { bg: T.successDeep, color: T.surface },
  completed:        { bg: T.successDeep, color: T.surface },
  cancelled:        { bg: T.surfaceSection, color: T.textMuted },
  confirmed:        { bg: T.purpleBgAlt, color: T.purpleDeep },
  pending:          { bg: T.surfaceYellow, color: T.statusPendingText },
  new:              { bg: T.surfaceYellow, color: T.statusPendingText },
};

function OrderStatusPill({ status }: { status: string }) {
  const { t } = useTranslation();
  const s = STATUS_STYLE[status] ?? { bg: T.surfaceSection, color: T.textMuted };
  const label = t(`orders.status.${status}`, { defaultValue: status.replace(/_/g, " ") });
  return (
    <span style={{
      background: s.bg, color: s.color, borderRadius: 20, padding: "4px 14px",
      fontSize: 11, fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.5,
      whiteSpace: "nowrap", display: "inline-block",
    }}>
      {label}
    </span>
  );
}

// ── Contextual action button ─────────────────────────────────────────────────
function ActionButton({ order, onAction }: {
  order: Order & { type: string };
  onAction: (id: string, status: string) => void;
}) {
  const { t } = useTranslation();
  const s = order.status;
  const tp = order.type;
  const btnStyle = { background: T.brand, color: T.surface, border: "none", fontWeight: 700, borderRadius: 50, padding: "0 18px", height: 36, fontSize: 13 } as const;

  if (s === "preparing")
    return <Button size="small" style={btnStyle} onClick={() => onAction(order.id, "ready")}>{t("orders.actionMarkReady")}</Button>;
  if (s === "ready" && tp === "pickup")
    return <Button size="small" style={{ ...btnStyle, background: T.pickedUpBg }} onClick={() => onAction(order.id, "completed")}>{t("orders.actionPickedUp")}</Button>;
  if (s === "ready" && tp === "delivery")
    return <Button size="small" style={btnStyle} onClick={() => onAction(order.id, "out_for_delivery")}>{t("orders.actionOutForDelivery")}</Button>;
  if (s === "out_for_delivery" || s === "in_transit")
    return <Button size="small" style={{ ...btnStyle, background: T.successDeep }} onClick={() => onAction(order.id, "delivered")}>{t("orders.actionDelivered")}</Button>;
  return null;
}

export function OrdersScreen() {
  const { t } = useTranslation();
  const { message } = App.useApp();
  const navigate = useNavigate();
  const [page, setPage] = useState(1);
  const [statusTab, setStatusTab] = useState<string>("all");
  const [typeFilter, setTypeFilter] = useState<string>("all");
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const STATUS_TABS = [
    { key: "all", label: t("orders.filterAll") },
    { key: "preparing", label: t("orders.statusTabPreparing") },
    { key: "ready", label: t("orders.statusTabReady") },
    { key: "out_for_delivery", label: t("orders.statusTabOutForDelivery") },
    { key: "completed", label: t("orders.statusTabCompleted") },
    { key: "cancelled", label: t("orders.statusTabCancelled") },
  ];

  const { data, isLoading } = useAdminOrders({
    page,
    limit: 20,
    status: statusTab !== "all" ? statusTab : undefined,
    type: typeFilter !== "all" ? typeFilter : undefined,
  });

  const { data: orderDetail } = useAdminOrder(selectedId ?? "");
  const cancelOrder = useAdminCancelOrder();
  const updateStatus = useAdminUpdateOrderStatus();
  const { data: statsData } = useDashboardStats();
  const stats = statsData?.data;
  const activeOrders = (stats?.preparingNow ?? 0) + (stats?.readyForPickup ?? 0) + (stats?.readyForDelivery ?? 0);

  const [cancelTarget, setCancelTarget] = useState<Order | null>(null);
  const [cancelForm] = Form.useForm<{ reason: string }>();

  const TERMINAL = new Set(["cancelled", "completed", "delivered"]);

  const onCancel = async ({ reason }: { reason: string }) => {
    if (!cancelTarget) return;
    try {
      await cancelOrder.mutateAsync({ id: cancelTarget.id, reason });
      void message.success(t("orders.cancelSuccess"));
      setCancelTarget(null);
      cancelForm.resetFields();
    } catch {
      void message.error(t("orders.cancelFailed"));
    }
  };

  const onAction = async (id: string, status: string) => {
    try {
      await updateStatus.mutateAsync({ id, status });
    } catch {
      void message.error(t("orders.updateStatusFailed"));
    }
  };

  const colHeader = (label: string) => (
    <span style={{ fontSize: 11, fontWeight: 600, color: T.textMuted, letterSpacing: 0.6, textTransform: "uppercase" }}>{label}</span>
  );

  const columns: ColumnsType<Order> = [
    {
      title: colHeader(t("orders.colOrderId")),
      dataIndex: "order_code", key: "order_code", width: 160,
      render: (v, row) => {
        const ord = row as Order & { type: string };
        return (
          <div>
            <div style={{ fontWeight: 700, fontSize: 14, color: T.textDark }}>#{v ?? row.id.slice(-8)}</div>
            <div style={{ display: "flex", alignItems: "center", gap: 4, marginTop: 3 }}>
              {ord.type === "delivery"
                ? <CarOutlined style={{ fontSize: 11, color: T.textMuted }} />
                : <ShoppingOutlined style={{ fontSize: 11, color: T.textMuted }} />}
              <span style={{ fontSize: 11, color: T.textMuted, fontWeight: 600, textTransform: "uppercase", letterSpacing: 0.3 }}>{t(`orders.type.${ord.type}`, { defaultValue: ord.type })}</span>
            </div>
          </div>
        );
      },
    },
    {
      title: colHeader(t("orders.colCustomer")),
      key: "customer", width: 180,
      render: (_, row) => {
        const cust = (row as Order & { customer?: { name?: string; phone?: string } | null }).customer;
        return (
          <div>
            <div style={{ fontWeight: 600, fontSize: 13, color: T.textDark }}>{cust?.name ?? "—"}</div>
            {cust?.phone && <div style={{ fontSize: 12, color: T.textMuted, marginTop: 2 }}>{cust.phone}</div>}
          </div>
        );
      },
    },
    {
      title: colHeader(t("orders.colAmount")),
      dataIndex: "total", key: "total", width: 120,
      render: (v) => <span style={{ fontWeight: 700, fontSize: 14, color: T.textDark }}>RM{v}</span>,
    },
    {
      title: colHeader(t("orders.colOrderTime")),
      dataIndex: "created_at", key: "created_at", width: 140,
      render: (v) => (
        <div>
          <div style={{ fontWeight: 600, fontSize: 13, color: T.textDark }}>{dayjs(v).format("h:mm A")}</div>
          <div style={{ fontSize: 12, color: T.textMuted, marginTop: 2 }}>{dayjs(v).format("D MMM YYYY")}</div>
        </div>
      ),
    },
    {
      title: colHeader(t("orders.colStatus")),
      dataIndex: "status", key: "status", width: 170,
      render: (v) => <OrderStatusPill status={v} />,
    },
    {
      title: colHeader(t("orders.colAction")),
      key: "actions", width: 200, fixed: "right" as const,
      render: (_, row) => {
        const ord = row as Order & { type: string };
        return (
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <ActionButton order={ord} onAction={onAction} />
            <Dropdown
              trigger={["click"]}
              menu={{
                items: [
                  { key: "details", label: <span style={{ fontWeight: 600, fontSize: 13, letterSpacing: 0.4, textTransform: "uppercase" }}>{t("orders.menuOverview")}</span>, onClick: () => setSelectedId(row.id) },
                  { key: "overview", label: <span style={{ fontWeight: 600, fontSize: 13, letterSpacing: 0.4, textTransform: "uppercase" }}>{t("orders.menuFullDetails")}</span>, onClick: () => navigate(`/orders/${row.id}`) },
                  { key: "cancel", label: <span style={{ fontWeight: 600, fontSize: 13, letterSpacing: 0.4, color: TERMINAL.has(row.status) ? T.textMuted : T.dangerMid, textTransform: "uppercase" }}>{t("orders.menuCancelOrder")}</span>, disabled: TERMINAL.has(row.status), onClick: () => { cancelForm.resetFields(); setCancelTarget(row); } },
                ],
              }}
            >
              <EllipsisOutlined style={{ fontSize: 20, color: T.textBody, cursor: "pointer", padding: "0 4px" }} />
            </Dropdown>
          </div>
        );
      },
    },
  ];

  return (
    <AdminShell>
      <div style={{ background: T.bg, minHeight: "100%", padding: "4px 0 32px" }}>

        {/* Header */}
        <div style={{ marginBottom: 20 }}>
          <h1 style={{ fontSize: 28, fontWeight: 800, color: T.textDark, margin: 0 }}>{t("orders.listHeading")}</h1>
          <div style={{ display: "flex", alignItems: "center", gap: 6, marginTop: 4 }}>
            <span style={{ width: 8, height: 8, borderRadius: "50%", background: "#22C55E", display: "inline-block" }} />
            <span style={{ fontSize: 13, color: T.textBody }}>{t("orders.liveFeedActive", { count: activeOrders })}</span>
          </div>
        </div>

        {/* Filter bar */}
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20 }}>
          {/* Status tabs */}
          <div style={{ display: "flex", border: "1px solid #E5E7EB", borderRadius: 8, overflow: "hidden", background: T.surface }}>
            {STATUS_TABS.map((tab) => (
              <button
                key={tab.key}
                onClick={() => { setStatusTab(tab.key); setPage(1); }}
                style={{
                  padding: "8px 20px", fontSize: 13, fontWeight: 600, border: "none", cursor: "pointer",
                  background: statusTab === tab.key ? T.brand : T.surface,
                  color: statusTab === tab.key ? T.surface : T.textDark,
                  transition: "background .15s, color .15s",
                  borderRight: "1px solid #E5E7EB",
                }}
              >
                {tab.label}
              </button>
            ))}
          </div>

          {/* Type filter */}
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            <span style={{ fontSize: 13, fontWeight: 600, color: T.textBody }}>{t("orders.filterType")}</span>
            <div style={{ display: "flex", border: "1px solid #E5E7EB", borderRadius: 6, overflow: "hidden", background: T.surface }}>
              {(["all", "pickup", "delivery"] as const).map((tp) => (
                <button
                  key={tp}
                  onClick={() => { setTypeFilter(tp); setPage(1); }}
                  style={{
                    padding: "6px 14px", fontSize: 12, fontWeight: 600, border: "none", cursor: "pointer",
                    background: typeFilter === tp ? T.textDark : T.surface,
                    color: typeFilter === tp ? T.surface : T.textDark,
                    transition: "background .15s, color .15s",
                    borderRight: "1px solid #E5E7EB",
                    textTransform: "capitalize",
                  }}
                >
                  {tp === "all" ? t("orders.filterAll") : t(`orders.type.${tp}`, { defaultValue: tp })}
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Table */}
        <div style={{ background: T.surface, borderRadius: 12, overflow: "hidden", boxShadow: "0 1px 6px rgba(0,0,0,.07)" }}>
          <Table<Order>
            columns={columns}
            dataSource={data?.data ?? []}
            rowKey="id"
            loading={isLoading}
            pagination={{
              current: page,
              total: data?.meta.total ?? 0,
              pageSize: 20,
              onChange: (p) => setPage(p),
              style: { padding: "12px 20px" },
            }}
            size="middle"
            scroll={{ x: 1000 }}
            rowClassName={() => "orders-table-row"}
            components={{
              header: {
                cell: (props: React.ThHTMLAttributes<HTMLTableCellElement>) => (
                  <th
                    {...props}
                    style={{
                      ...props.style,
                      background: T.bg,
                      padding: "14px 16px",
                      fontSize: 11,
                      fontWeight: 700,
                      color: T.textMuted,
                      letterSpacing: "0.07em",
                      textTransform: "uppercase",
                      borderBottom: "1px solid #E5E7EB",
                    }}
                  />
                ),
              },
              body: {
                row: (props: React.HTMLAttributes<HTMLTableRowElement>) => (
                  <tr
                    {...props}
                    style={{ ...props.style, borderBottom: "1px solid #F3F4F6" }}
                  />
                ),
                cell: (props: React.TdHTMLAttributes<HTMLTableCellElement>) => (
                  <td {...props} style={{ ...props.style, padding: "20px 16px", verticalAlign: "middle" }} />
                ),
              },
            }}
          />
        </div>

      </div>

      {/* Order Detail Drawer */}
      <Drawer
        open={!!selectedId}
        onClose={() => setSelectedId(null)}
        width={420}
        closeIcon={false}
        styles={{ body: { padding: 0 }, header: { display: "none" } }}
      >
        {orderDetail?.data && (() => {
          const od = orderDetail.data;
          const odExt = od as unknown as {
            order_code?: string;
            customer?: { name?: string; phone?: string } | null;
            payment_method?: string;
            voucher_code?: string;
            special_note?: string | null;
            items?: OrderItem[];
            sst_rate?: number;
          };
          const TERMINAL_STATUSES = new Set(["completed", "delivered", "cancelled"]);
          const custName = odExt.customer?.name ?? "—";
          const initials = custName === "—" ? "?" : custName.split(" ").filter(Boolean).map((w) => w[0]).slice(0, 2).join("").toUpperCase();
          const itemCount = odExt.items?.length ?? 0;
          const ord2 = od as Order & { type: string };

          const drawerActionLabel = (() => {
            const s = od.status; const tp = ord2.type;
            if (s === "preparing") return { label: t("orders.actionMarkAsReady"), next: "ready", bg: T.brand };
            if (s === "ready" && tp === "pickup") return { label: t("orders.actionPickedUp"), next: "completed", bg: T.pickedUpBg };
            if (s === "ready" && tp === "delivery") return { label: t("orders.actionOutForDelivery"), next: "out_for_delivery", bg: T.brand };
            if (s === "out_for_delivery" || s === "in_transit") return { label: t("orders.actionDelivered"), next: "delivered", bg: T.successDeep };
            return null;
          })();

          return (
            <div style={{ display: "flex", flexDirection: "column", height: "100%" }}>
              {/* Scrollable body */}
              <div style={{ flex: 1, overflowY: "auto", padding: "28px 24px", paddingBottom: !TERMINAL_STATUSES.has(od.status) ? 100 : 28 }}>

                {/* Close button */}
                <button
                  onClick={() => setSelectedId(null)}
                  style={{ position: "absolute", top: 20, right: 20, background: "none", border: "none", cursor: "pointer", fontSize: 18, color: T.textBody, lineHeight: 1, zIndex: 10 }}
                >
                  ✕
                </button>

                {/* Order code + status pill */}
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", paddingRight: 36, marginBottom: 6 }}>
                  <span style={{ fontSize: 26, fontWeight: 800, color: T.textDark }}>#{odExt.order_code ?? od.id.slice(-8)}</span>
                  <OrderStatusPill status={od.status} />
                </div>

                {/* Timestamp */}
                <div style={{ fontSize: 13, color: T.textMuted, marginBottom: 20 }}>
                  {dayjs(od.created_at).format("h:mm A")} • {dayjs(od.created_at).format("D MMM YYYY")}
                </div>

                {/* Channel + Paid tags */}
                <div style={{ display: "flex", gap: 8, marginBottom: 28 }}>
                  <span style={{ display: "inline-flex", alignItems: "center", gap: 6, padding: "5px 14px", border: "1px solid #D1D5DB", borderRadius: 20, fontSize: 13, color: T.textDark, background: T.surface }}>
                    {od.type === "delivery" ? <CarOutlined style={{ fontSize: 13 }} /> : <ShoppingOutlined style={{ fontSize: 13 }} />}
                    {od.type === "delivery" ? t("orders.drawerChannelDelivery") : t("orders.drawerChannelPickup")}
                  </span>
                  <span style={{ display: "inline-flex", alignItems: "center", gap: 5, padding: "5px 14px", border: "1.5px solid #16A34A", borderRadius: 20, fontSize: 13, color: T.successBright, fontWeight: 600, background: T.surface }}>
                    ✓ {t("orders.drawerPaid")}
                  </span>
                </div>

                {/* CUSTOMER DETAILS */}
                <div style={{ fontSize: 11, fontWeight: 700, color: T.textMuted, letterSpacing: "0.08em", textTransform: "uppercase", marginBottom: 12 }}>{t("orders.drawerCustomerDetails")}</div>
                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 10 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                    <div style={{ width: 44, height: 44, borderRadius: "50%", background: T.border, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 15, fontWeight: 700, color: T.textBody, flexShrink: 0 }}>
                      {initials}
                    </div>
                    <div>
                      <div style={{ fontSize: 15, fontWeight: 700, color: T.textDark }}>{custName}</div>
                      {odExt.customer?.phone && <div style={{ fontSize: 13, color: T.textMuted, marginTop: 2 }}>{odExt.customer.phone}</div>}
                    </div>
                  </div>
                  {odExt.customer?.phone && (
                    <a
                      href={`tel:${odExt.customer.phone}`}
                      style={{ width: 36, height: 36, borderRadius: "50%", border: "1px solid #E5E7EB", display: "flex", alignItems: "center", justifyContent: "center", color: T.textBody, flexShrink: 0, textDecoration: "none" }}
                    >
                      <PhoneOutlined style={{ fontSize: 16 }} />
                    </a>
                  )}
                </div>

                {/* Pickup / delivery time row */}
                <div style={{ background: T.bg, borderRadius: 8, padding: "10px 14px", display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 28 }}>
                  <span style={{ fontSize: 13, color: T.siderHover }}>{od.type === "delivery" ? t("orders.drawerDeliveryTime") : t("orders.drawerPickupTime")}</span>
                  <span style={{ fontSize: 13, fontWeight: 700, color: T.textDark }}>{t("orders.drawerAsap")}</span>
                </div>

                {/* ORDER ITEMS */}
                <div style={{ fontSize: 11, fontWeight: 700, color: T.textMuted, letterSpacing: "0.08em", textTransform: "uppercase", marginBottom: 16 }}>{t("orders.drawerOrderItemsCount", { count: itemCount })}</div>
                {odExt.items?.map((item, i) => {
                  const extrasTotal = item.options.reduce((s, o) => s + parseFloat(o.extra_charge), 0);
                  const unitPrice = parseFloat(item.price) + extrasTotal;
                  return (
                    <div key={i} style={{ display: "flex", alignItems: "flex-start", gap: 12, marginBottom: 20 }}>
                      <div style={{ width: 52, height: 52, borderRadius: 8, background: T.surfaceSection, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 18, fontWeight: 700, color: T.textMuted, flexShrink: 0 }}>
                        {item.name.charAt(0)}
                      </div>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={{ fontWeight: 700, fontSize: 13.5, color: T.textDark, lineHeight: 1.35 }}>{item.name}</div>
                        {(item.options.length > 0 || item.note) && (
                          <div style={{ fontSize: 12, color: T.textMuted, marginTop: 3 }}>
                            {[item.options.map((o) => o.label).join(", "), item.note].filter(Boolean).join(" • ")}
                          </div>
                        )}
                        <div style={{ fontSize: 13, color: T.textBody, marginTop: 4, fontWeight: 500 }}>RM {unitPrice.toFixed(2)}</div>
                      </div>
                      <div style={{ minWidth: 32, height: 32, borderRadius: "50%", background: T.statusPreparingBg, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 12, fontWeight: 700, color: T.brand, flexShrink: 0 }}>
                        {item.qty}×
                      </div>
                    </div>
                  );
                })}

                {/* Price breakdown */}
                <div style={{ borderTop: "1px solid #F3F4F6", paddingTop: 16, marginTop: 4 }}>
                  {([
                    { label: t("orders.drawerSubtotal"), value: `RM ${od.subtotal}` },
                    parseFloat(od.voucher_discount) > 0 ? { label: t("orders.discountWithCode", { code: odExt.voucher_code ?? t("orders.voucherFallback") }), value: `-RM ${od.voucher_discount}`, red: true } : null,
                    parseFloat(od.sst_amount) > 0 ? { label: t("orders.sstWithRate", { rate: odExt.sst_rate ?? 8 }), value: `RM ${od.sst_amount}` } : null,
                    parseFloat(od.delivery_fee) > 0 ? { label: t("orders.drawerDelivery"), value: `RM ${od.delivery_fee}` } : null,
                  ] as Array<{ label: string; value: string; red?: boolean } | null>).filter(Boolean).map((row, i) => row && (
                    <div key={i} style={{ display: "flex", justifyContent: "space-between", marginBottom: 10 }}>
                      <span style={{ fontSize: 13, color: T.siderHover }}>{row.label}</span>
                      <span style={{ fontSize: 13, color: row.red ? T.dangerMid : T.textDark }}>{row.value}</span>
                    </div>
                  ))}
                </div>

                {/* Total Amount */}
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "14px 0", borderTop: "2px solid #F3F4F6", marginTop: 4 }}>
                  <span style={{ fontSize: 16, fontWeight: 800, color: T.textDark }}>{t("orders.drawerTotalAmount")}</span>
                  <span style={{ fontSize: 22, fontWeight: 800, color: T.brand }}>RM {od.total}</span>
                </div>

                {/* Payment method */}
                <div style={{ background: T.bg, borderRadius: 10, padding: "12px 16px", marginTop: 4 }}>
                  <div style={{ fontSize: 10, fontWeight: 700, color: T.textMuted, letterSpacing: "0.08em", textTransform: "uppercase", marginBottom: 8 }}>{t("orders.drawerPaymentMethod")}</div>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                    <span style={{ fontSize: 14, fontWeight: 600, color: T.textDark }}>{odExt.payment_method ?? "—"}</span>
                    <span style={{ background: T.successDeep, color: T.surface, fontSize: 11, fontWeight: 700, padding: "3px 10px", borderRadius: 4, letterSpacing: 0.5 }}>{t("orders.drawerPaidBadge")}</span>
                  </div>
                </div>

              </div>

              {/* Footer actions */}
              {!TERMINAL_STATUSES.has(od.status) && (
                <div style={{ position: "absolute", bottom: 0, left: 0, right: 0, background: T.surface, borderTop: "1px solid #E5E7EB", padding: "16px 24px", display: "flex", gap: 12 }}>
                  <Button
                    style={{ flex: 1, height: 48, fontWeight: 600, borderRadius: 10, fontSize: 14 }}
                    onClick={() => { setSelectedId(null); cancelForm.resetFields(); setCancelTarget(od); }}
                  >
                    {t("orders.cancelOrderAction")}
                  </Button>
                  {drawerActionLabel && (
                    <Button
                      style={{ flex: 1.5, height: 48, fontWeight: 700, borderRadius: 10, fontSize: 14, background: drawerActionLabel.bg, color: T.surface, border: "none" }}
                      onClick={async () => { await onAction(od.id, drawerActionLabel.next); setSelectedId(null); }}
                    >
                      {drawerActionLabel.label}
                    </Button>
                  )}
                </div>
              )}
            </div>
          );
        })()}
      </Drawer>

      <Modal
        open={!!cancelTarget}
        title={t("orders.cancelModalTitle")}
        onCancel={() => { setCancelTarget(null); cancelForm.resetFields(); }}
        onOk={() => void cancelForm.submit()}
        okText={t("orders.cancelConfirm")}
        okButtonProps={{ danger: true, loading: cancelOrder.isPending }}
        cancelText={t("common.back")}
      >
        <p style={{ color: T.textSecondary, marginBottom: 12 }}>
          {t("orders.cancelHint")}
        </p>
        <Form form={cancelForm} layout="vertical" onFinish={onCancel}>
          <Form.Item
            name="reason"
            label={t("orders.cancelReason")}
            rules={[{ required: true, min: 3, max: 500 }]}
          >
            <Input.TextArea rows={3} maxLength={500} showCount placeholder={t("orders.cancelReasonPlaceholder")} />
          </Form.Item>
        </Form>
      </Modal>
    </AdminShell>
  );
}
